For any $\bm{\eta}\in(0,\infty)^{\mathbb{N}}$, any $n\in\mathbb{N}$, and any $m\in[n]$ such that $\eta_m > 1$, we have
\begin{equation}
\begin{split}
	R_n(\bm{\eta}) &\geq \frac{ (\eta_m-1)^2 }{ ( 1 + \eta_{1:m-1} )^2 ( 1 + 2 \eta_{m+1:n} ) }, \\
	G_n(\bm{\eta}) &\geq \frac{ (\eta_m-1)^2 }{ ( 1 + 2 \eta_{1:m-1} ) ( 1 + \eta_{m+1:n} )^2 }.
\end{split}
\end{equation}
In particular, we have for any $n\in\mathbb{N}$,
\begin{equation}
\begin{split}
	\eta_n &\leq 1 + (1 + \eta_{1:n-1})\sqrt{R_n(\bm{\eta})}, \\
	\eta_n &\leq 1 + \sqrt{1 + 2\eta_{1:n-1}}\sqrt{G_n(\bm{\eta})}.
\end{split}
\end{equation}
